// KeyDeploymentEntry: One entry of keys/deployed.yaml: a human confirmed that
// all clients of the target, and the keyring of its mirror line, have the key.
// A release record gives the release NVR with the key; a key file record gives
// the sha256 and the set commit of a key file that config management installed
// without a release package (signing.html#record-forms).
type KeyDeploymentEntry struct {
	// Key id in sign.keys.
	Key    string   `json:"key"`
	Target TargetId `json:"target"`
	// Full fingerprint. It must equal the fingerprint of the key in sign.keys.
	Fingerprint string `json:"fingerprint"`
	// Release record: NVR of the release package with the dist tag, e.g.
	// slurm-release-26.05-3.el9.
	Release string `json:"release,omitempty"`
	// Key file record: the sha256 of the key file, as repoctl sign keyfile
	// --checksum prints it.
	Keyfile Sha256 `json:"keyfile,omitempty"`
	// Key file record: the set commit of the key file.
	Commit Commit `json:"commit,omitempty"`
	// Key id of the human who ran repoctl sign deployed.
	ConfirmedBy string `json:"confirmedBy"`
	At          Time   `json:"at"`
	Note        string `json:"note,omitempty"`
}

// KeyRemoval: A removal record for one target: a human confirmed that config
// management removed the key from all clients of the target.
type KeyRemoval struct {
	// Key id of the human who ran repoctl sign removed.
	ConfirmedBy string `json:"confirmedBy"`
	At          Time   `json:"at"`
	Note        string `json:"note,omitempty"`
}

// KeyRemovalEntry: One entry of removals in keys/deployed.yaml.
type KeyRemovalEntry struct {
	// Key id in sign.keys, state removed.
	Key         string   `json:"key"`
	Target      TargetId `json:"target"`
	Fingerprint string   `json:"fingerprint"`
	// Key id of the human who ran repoctl sign removed.
	ConfirmedBy string `json:"confirmedBy"`
	At          Time   `json:"at"`
	Note        string `json:"note,omitempty"`
}

type OnboardReport struct {
	Key   string              `json:"key"`
	Steps []OnboardReportStep `json:"steps"`
	// The command that the human runs next.
	Next string `json:"next,omitempty"`
	// sign offboard of a revoked key: each snapshot in the registry with a file
	// that the key signed, newest first.
	SignedSnapshots []OnboardReportSignedSnapshot `json:"signedSnapshots,omitempty"`
	// sign offboard only: the commands that config management runs on each client,
	// after the upgrade of the release package.
	ClientCommands []OnboardReportClientCommand `json:"clientCommands,omitempty"`
}

// MarshalJSON writes an empty list or object, never null, for each
// required list of OnboardReport.
func (v OnboardReport) MarshalJSON() ([]byte, error) {
	type plain OnboardReport
	p := plain(v)
	if p.Steps == nil {
		p.Steps = []OnboardReportStep{}
	}
	return json.Marshal(p)
}

type OnboardReportStep struct {
	N      int    `json:"n"`
	Name   string `json:"name"`
	Ok     bool   `json:"ok"`
	Detail string `json:"detail,omitempty"`
}

type OnboardReportSignedSnapshot struct {
	Target TargetId `json:"target"`
	// Publish id of the snapshot.
	Publish string `json:"publish"`
	Digest  Digest `json:"digest"`
	User    string `json:"user,omitempty"`
	Host    string `json:"host,omitempty"`
	// RPMs in the snapshot that the key signed.
	RPMs int `json:"rpms"`
	// The key signed the repomd.xml.asc of the snapshot.
	Repomd bool `json:"repomd"`
	Latest bool `json:"latest"`
}

type OnboardReportClientCommand struct {
	// The client OS of the command, e.g. EL9, EL10, both.
	OS string `json:"os"`
	// e.g. rpm -e gpg-pubkey-7c3a19f2.
	Command string `json:"command"`
	// e.g. EL10.1 and later.
	Note string `json:"note,omitempty"`
}
